const body = $input.first().json.body ?? {};
const context = body.context ?? {};
const pending = Array.isArray(context.pending_media) ? context.pending_media : [];

return [{
  json: {
    conversation_id: context.conversation_id,
    api: String(body.api_base_url ?? '').replace(/\/$/, ''),
    pending_media: pending,
    has_media: pending.length > 0,
  },
}];

const file = $('Recorrer archivos').first().json;
let b64 = '';
let mime = file.mime || 'application/octet-stream';

try {
  const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
  b64 = buffer.toString('base64');
  mime = file.mime || $input.first().binary?.data?.mimeType || mime;
} catch (error) {
  b64 = '';
}

const recipePrompt = `Eres una farmacéutica venezolana experta en leer récipes médicos escritos a mano o impresos.
Analiza la imagen y responde SOLO con el JSON pedido.

- is_prescription: true si es un récipe o indicación médica; false si es otra cosa (caja de un producto, documento, foto personal).
  Si es la foto de un producto, pon su nombre en items y is_prescription = false.
- legibility: "legible" si puedes leer con seguridad los medicamentos; "dudosa" si hay partes que no se leen bien; "ilegible" si está borrosa, cortada, oscura o no se entiende.
- items: cada medicamento con nombre, concentración (ej. "50 mg"), presentación (tabletas, jarabe…), cantidad indicada, indicaciones de uso y confidence entre 0 y 1.
- is_controlled_substance: true si es psicotrópico o estupefaciente (ej. clonazepam, alprazolam, tramadol, morfina, metilfenidato).
- NUNCA inventes ni completes un nombre que no se lee: baja la confianza y explica el problema en issues.
- issues: problemas de la imagen o de la lectura, en español y en pocas palabras.`;

const schema = {
  type: 'OBJECT',
  properties: {
    is_prescription: { type: 'BOOLEAN' },
    legibility: { type: 'STRING', enum: ['legible', 'dudosa', 'ilegible'] },
    overall_confidence: { type: 'NUMBER' },
    doctor_name: { type: 'STRING' },
    prescription_date: { type: 'STRING' },
    issues: { type: 'ARRAY', items: { type: 'STRING' } },
    items: {
      type: 'ARRAY',
      items: {
        type: 'OBJECT',
        properties: {
          medication_name: { type: 'STRING' },
          concentration: { type: 'STRING' },
          presentation: { type: 'STRING' },
          quantity_text: { type: 'STRING' },
          dosage_instructions: { type: 'STRING' },
          confidence: { type: 'NUMBER' },
          is_controlled_substance: { type: 'BOOLEAN' },
        },
        required: ['medication_name', 'confidence'],
      },
    },
  },
  required: ['is_prescription', 'legibility', 'items'],
};

const isImage = file.type === 'image';

const request = isImage
  ? {
      contents: [{ role: 'user', parts: [{ text: recipePrompt }, { inline_data: { mime_type: mime, data: b64 } }] }],
      generationConfig: { temperature: 0.1, responseMimeType: 'application/json', responseSchema: schema },
    }
  : {
      contents: [{ role: 'user', parts: [
        { text: 'Transcribe literalmente, en español, esta nota de voz de un cliente de una farmacia en Venezuela. Devuelve solo el texto, sin comentarios. Si no se entiende nada, devuelve [inaudible].' },
        { inline_data: { mime_type: mime, data: b64 } },
      ] }],
      generationConfig: { temperature: 0 },
    };

return [{ json: { ...file, mime, gemini_request: request } }];

const file = $('Preparar petición a Gemini').first().json;
const prep = $('Preparar').first().json;
const parts = $input.first().json?.candidates?.[0]?.content?.parts ?? [];
const text = parts.map((part) => part.text ?? '').join('').trim();
const clamp = (value) => (typeof value === 'number' && Number.isFinite(value) ? Math.min(1, Math.max(0, value)) : null);

if (file.type === 'image') {
  let reading;
  try {
    reading = JSON.parse(text);
  } catch (error) {
    reading = { is_prescription: true, legibility: 'ilegible', items: [], issues: ['No se pudo leer la imagen con el modelo'] };
  }

  const items = (Array.isArray(reading.items) ? reading.items : [])
    .filter((item) => item && item.medication_name)
    .map((item) => ({ ...item, confidence: clamp(item.confidence) }));

  return [{
    json: {
      save_method: 'POST',
      save_url: `${prep.api}/conversations/${prep.conversation_id}/prescription-readings`,
      save_body: {
        whatsapp_message_id: file.message_id,
        is_prescription: reading.is_prescription !== false,
        legibility: ['legible', 'dudosa', 'ilegible'].includes(reading.legibility) ? reading.legibility : 'dudosa',
        overall_confidence: clamp(reading.overall_confidence),
        doctor_name: reading.doctor_name || null,
        prescription_date: reading.prescription_date || null,
        issues: Array.isArray(reading.issues) ? reading.issues.slice(0, 10) : [],
        items: items.slice(0, 20),
        raw_response: reading,
      },
    },
  }];
}

return [{
  json: {
    save_method: 'POST',
    save_url: `${prep.api}/messages/${file.message_id}/transcription`,
    save_body: { transcription: text || '[Nota de voz que no se pudo transcribir]' },
  },
}];

